CREATE TABLE "accounts_userappdata" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "key" varchar(64) NOT NULL, "value" text NOT NULL CHECK ((JSON_VALID("value") OR "value" IS NULL)), "byte_size" integer unsigned NOT NULL CHECK ("byte_size" >= 0), "updated_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_accounts_user_app_data_key" UNIQUE ("user_id", "key"))
